WITH valid AS (SELECT *, CASE WHEN country = 'SG' THEN 1 ELSE 0 END AS is_sg FROM customers WHERE signup_date >= DATE '2023-05-07' AND segment IS NOT NULL), scored AS (SELECT id, name, country, segment, signup_date, credit_limit, MIN(credit_limit) OVER (PARTITION BY city ORDER BY signup_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_credit_limit, SUM(credit_limit) OVER (PARTITION BY city ORDER BY signup_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_credit_limit, COUNT(credit_limit) OVER (PARTITION BY city ORDER BY signup_date, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_credit_limit, CUME_DIST() OVER (PARTITION BY DATE_TRUNC('MONTH', signup_date), segment ORDER BY age DESC NULLS LAST) AS age_cume_dist FROM valid), cleaned AS (SELECT id, country, segment, signup_date, credit_limit, last3_min_credit_limit, last3_sum_credit_limit, last3_count_credit_limit, COALESCE(segment, 'unassigned') AS segment_filled, COALESCE(segment, 'NONE') AS resolved_segment FROM scored WHERE segment IS NOT NULL), with_latest AS (SELECT s.id, s.signup_date, s.credit_limit, s.last3_sum_credit_limit, s.segment_filled, x.account_status, x.balance FROM cleaned s LEFT JOIN LATERAL (SELECT c.status AS account_status, c.balance FROM accounts c WHERE c.customer_id = s.id ORDER BY c.opened_date DESC, c.id DESC LIMIT 1) x ON TRUE), kept AS (SELECT s.* FROM with_latest s WHERE NOT EXISTS (SELECT 1 FROM accounts c WHERE c.customer_id = s.id AND c.opened_date <= s.signup_date)) SELECT account_status, SIZE(COLLECT_SET(account_status)) AS num_account_status, COUNT(DISTINCT id) AS distinct_ids, GROUPING_ID() AS grouping_level FROM kept GROUP BY ROLLUP (account_status) HAVING num_account_status > 1 ORDER BY distinct_ids NULLS FIRST;
